INSERT INTO `chapters` (`id`, `discipline_id`, `titre`, `slug`, `description`, `tome`, `niveau`, `ordre`, `order_num`, `created_at`) VALUES
(90, 2, 'Constitution et Cohésion de la Matière', 'constitution-et-cohesion-de-la-matiere', 'Structure microscopique, états de la matière, solides métalliques, ioniques et polymères.', 'Belin Sup Chimie - CAPES & Agrégation', 'l1', 1, 1, '2026-08-15 12:48:33'),
(91, 2, 'Aspects Énergétiques et Cinétiques', 'aspects-energetiques-et-cinetiques', 'Thermochimie, enthalpie de réaction, cinétique chimique et mécanismes catalytiques.', 'Belin Sup Chimie - CAPES & Agrégation', 'l2', 2, 2, '2026-08-15 12:48:33'),
(92, 2, 'Équilibres Chimiques en Solution Aquatique', 'equilibres-chimiques-en-solution-aquatique', 'Réactions acide-base, complexation, précipitation, solubilité et oxydoréduction.', 'Belin Sup Chimie - CAPES & Agrégation', 'l2', 3, 3, '2026-08-15 12:48:33'),
(93, 2, 'Synthèses et Réactivité en Chimie Organique', 'syntheses-et-reactivite-en-chimie-organique', 'Stéréochimie, hydrocarbures, fonctions monovalentes, polyvalentes et stratégies de synthèse.', 'Belin Sup Chimie - CAPES & Agrégation', 'l3', 4, 4, '2026-08-15 12:48:33'),
(94, 2, 'Chimie Industrielle, Techniques d Analyse & Annexes', 'chimie-industrielle-techniques-d-analyse-et-annexes', 'Procédés industriels, spectroscopie, chromatographie, nomenclature et annales.', 'Belin Sup Chimie - CAPES & Agrégation', 'master', 5, 5, '2026-08-15 12:48:33'),
(100, 1, 'Ondes Mécaniques & Acoustiques', 'ondes-mecaniques-et-acoustiques', 'Propagation d ondes 1D, résonance sur corde vibrante, onde de gravitation dans les liquides et acoustique dans les fluides.', 'Tome 1 : Ondes Mécaniques', 'l2', 1, 1, '2026-08-15 14:55:50'),
(101, 1, 'Ondes Électromagnétiques dans le Vide et les Milieux', 'ondes-electromagnetiques-vide-et-milieux', 'Équations de Maxwell, vecteur de Poynting, induction électromagnétique et propagation d OPPM dans le vide.', 'Tome 2 : Ondes Électromagnétiques', 'l2', 1, 1, '2026-08-15 14:55:50'),
(102, 1, 'Ondes Électromagnétiques dans les Diélectriques & Anisotropes', 'ondes-electromagnetiques-dielectriques-et-anisotropes', 'Propagation guidée, réflexion de Fresnel, diélectriques isotropes, conducteurs métalliques et biréfringence.', 'Tome 3 : Diélectriques & Anisotropie', 'l3', 1, 1, '2026-08-15 14:55:50'),
(103, 1, 'Optique Géométrique & Ondulatoire', 'optique-geometrique-et-ondulatoire', 'Lois de Snell-Descartes, instruments d optique, lentilles minces, interférences et diffraction.', 'H-Prépa Optique', 'l1', 1, 1, '2026-08-15 14:55:50'),
(104, 1, 'Mécanique du Point et du Solide', 'mecanique-du-point-et-du-solide', 'Cinématique du point matériel, lois de Newton, moment cinétique, mécanique des solides et mécanique des fluides.', 'H-Prépa Mécanique', 'l2', 1, 1, '2026-08-15 14:55:50'),
(105, 1, 'Thermodynamique', 'thermodynamique', 'Premier et second principes, bilans d énergie, entropie, potentiels thermodynamiques et transitions de phase.', 'Thermodynamique', 'l2', 1, 1, '2026-08-15 15:04:47');
