-- Cleaned SQL dump from user
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `books`;
CREATE TABLE `books` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `titre` varchar(255) NOT NULL,
  `collection` varchar(100) NOT NULL,
  `auteur` varchar(150) DEFAULT NULL,
  `discipline` varchar(50) NOT NULL DEFAULT 'Physique',
  `niveau` varchar(100) NOT NULL DEFAULT 'CPGE',
  `pdf_file` varchar(500) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_books_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `chapters`;
CREATE TABLE `chapters` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `discipline_id` int(10) UNSIGNED NOT NULL,
  `titre` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `tome` varchar(150) DEFAULT NULL,
  `niveau` enum('l1','l2','l3','master','autre') NOT NULL DEFAULT 'l1',
  `ordre` int(10) UNSIGNED NOT NULL DEFAULT 1,
  `order_num` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chapters_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `concours`;
CREATE TABLE `concours` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `ecole` varchar(255) NOT NULL,
  `annee` int(10) UNSIGNED NOT NULL,
  `filiere` varchar(100) NOT NULL DEFAULT 'Toutes',
  `matiere` varchar(100) NOT NULL DEFAULT 'Physique',
  `epreuve` varchar(255) NOT NULL,
  `titre` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `slug` varchar(255) NOT NULL,
  `enonce_file` varchar(500) DEFAULT NULL,
  `correction_file` varchar(500) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_concours_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
